#include <Wire.h>
#include <Adafruit_BME280.h>
Adafruit_BME280 bme;

void setup() {
  Serial.begin(115200);
  Wire.begin({{sda_pin}}, {{scl_pin}});
  if (!bme.begin({{i2c_addr}})) Serial.println("BME280 not found");
}

void loop() {
  Serial.printf("T=%.2f H=%.2f P=%.2f\n", bme.readTemperature(), bme.readHumidity(), bme.readPressure() / 100.0);
  delay(2000);
}
